macro_rules! on_dot_typed {
    () => {
        # [doc = " Returns an edit which should be applied when a dot ('.') is typed on a blank line, indenting the line appropriately."] fn on_dot_typed (file : & SourceFile , offset : TextSize) -> Option < TextEdit > { let whitespace = file . syntax () . token_at_offset (offset) . left_biased () . and_then (ast :: Whitespace :: cast) ? ; let current_indent = { let text = whitespace . text () ; let (_prefix , suffix) = text . rsplit_once ('\n') ? ; suffix } ; let current_indent_len = TextSize :: of (current_indent) ; let parent = whitespace . syntax () . parent () ? ; let receiver = if let Some (field_expr) = ast :: FieldExpr :: cast (parent . clone ()) { field_expr . expr () ? } else if let Some (method_call_expr) = ast :: MethodCallExpr :: cast (parent . clone ()) { method_call_expr . receiver () ? } else { return None ; } ; let receiver_is_multiline = receiver . syntax () . text () . find_char ('\n') . is_some () ; let target_indent = match (receiver , receiver_is_multiline) { (ast :: Expr :: MethodCallExpr (expr) , true) => { expr . dot_token () . as_ref () . map (IndentLevel :: from_token) } (ast :: Expr :: FieldExpr (expr) , true) => { expr . dot_token () . as_ref () . map (IndentLevel :: from_token) } (_ , true) => Some (IndentLevel :: from_node (& parent)) , _ => None , } ; let target_indent = match target_indent { Some (x) => x , None => IndentLevel :: from_node (& parent) + 1 , } . to_string () ; if current_indent_len == TextSize :: of (& target_indent) { return None ; } Some (TextEdit :: replace (TextRange :: new (offset - current_indent_len , offset) , target_indent)) }
    };
}

on_dot_typed!();